select 'data.boards', md5(coalesce(string_agg(b::text, '|' order by b.id), '')) from public.boards b
union all select 'data.labels', md5(coalesce(string_agg(l::text, '|' order by l.id), '')) from public.labels l
union all select 'data.tasks', md5(coalesce(string_agg(t::text, '|' order by t.id), '')) from public.tasks t
union all select 'data.task_labels', md5(coalesce(string_agg(x::text, '|' order by x.task_id, x.label_id), '')) from public.task_labels x
union all select 'rows', (select count(*) from public.boards)||'/'||(select count(*) from public.tasks)||'/'||(select count(*) from public.labels)||'/'||(select count(*) from public.task_labels)
union all select 'schema.columns', md5(string_agg(table_name||'.'||column_name||':'||data_type||':'||coalesce(column_default,'')||':'||is_nullable, '|' order by table_name, column_name)) from information_schema.columns where table_schema='public' and table_name in ('boards','labels','tasks','task_labels')
union all select 'schema.policies', md5(string_agg(tablename||'.'||policyname||':'||cmd||':'||coalesce(qual,'')||':'||coalesce(with_check,''), '|' order by tablename, policyname)) from pg_policies where schemaname='public' and tablename in ('boards','labels','tasks','task_labels')
union all select 'schema.grants', md5(string_agg(table_name||':'||grantee||':'||privilege_type, '|' order by table_name, grantee, privilege_type)) from information_schema.role_table_grants where table_schema='public' and table_name in ('boards','labels','tasks','task_labels')
union all select 'schema.functions', md5(string_agg(p.proname||':'||pg_get_functiondef(p.oid)||':'||coalesce(array_to_string(p.proacl,','),''), '|' order by p.proname)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname not like 'agent\_%'
union all select 'schema.constraints', md5(string_agg(conrelid::regclass||'.'||conname||':'||pg_get_constraintdef(oid), '|' order by conrelid::regclass::text, conname)) from pg_constraint where connamespace='public'::regnamespace and conrelid::regclass::text in ('boards','labels','tasks','task_labels')
union all select 'schema.triggers_indexes', md5(coalesce((select string_agg(tgname,'|' order by tgname) from pg_trigger where not tgisinternal and tgrelid::regclass::text in ('boards','labels','tasks','task_labels')),'')||'#'||(select string_agg(indexname||indexdef,'|' order by indexname) from pg_indexes where schemaname='public' and tablename in ('boards','labels','tasks','task_labels')))
union all select 'm11.objects', (select count(*) from pg_class where relnamespace='public'::regnamespace and relname like 'agent\_%' and relkind='r')||' tables, '||(select count(*) from pg_proc where pronamespace='public'::regnamespace and proname like 'agent\_%')||' functions';
